pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    DEP_BANK c;
    function setUp() public { c = new DEP_BANK(); }
    function testFuzz_property(uint256 _val) public {
        vm.assume(_val < type(uint256).max / 2);
        c.SetMinSum(_val);
        c.Initialized();
        assertEq(c.MinSum(), _val);
    }
}
